from collections import Counter

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find the most common color to treat as background
    counts = Counter(val for row in grid for val in row)
    background_color = counts.most_common(1)[0][0]

    # Iterate over all colors 0-9
    for color in range(10):
        if color == background_color:
            continue

        # Find coordinates for this color
        coords = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    coords.append((r, c))

        # If exactly two pixels exist, fill the bounding box
        if len(coords) == 2:
            (r1, c1), (r2, c2) = coords
            r_min, r_max = min(r1, r2), max(r1, r2)
            c_min, c_max = min(c1, c2), max(c1, c2)

            for r in range(r_min, r_max + 1):
                for c in range(c_min, c_max + 1):
                    result[r][c] = color

    return result
